interface Specification<T> {
    boolean isSatisfiedBy(T candidate);
}

class Product {
    private String name;
    private boolean inStock;
    private double price;

    public Product(String name, boolean inStock, double price) {
        this.name = name;
        this.inStock = inStock;
        this.price = price;
    }

    public String getName() {
        return name;
    }

    public boolean isInStock() {
        return inStock;
    }

    public double getPrice() {
        return price;
    }
}

class InStockSpecification implements Specification<Product> {
    @Override
    public boolean isSatisfiedBy(Product candidate) {
        // independent rule: only looks at stock, knows nothing about price
        return candidate.isInStock();
    }
}

class PriceBelowSpecification implements Specification<Product> {
    private double limit;

    public PriceBelowSpecification(double limit) {
        this.limit = limit; // each instance owns its own threshold
    }

    @Override
    public boolean isSatisfiedBy(Product candidate) {
        // independent rule: only looks at price, knows nothing about stock
        return candidate.getPrice() < limit;
    }
}

class AndSpecification implements Specification<Product> {
    private Specification<Product> first;
    private Specification<Product> second;

    public AndSpecification(Specification<Product> first, Specification<Product> second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public boolean isSatisfiedBy(Product candidate) {
        // combinator: delegates to both wrapped specifications, combines with AND
        return first.isSatisfiedBy(candidate) && second.isSatisfiedBy(candidate);
    }
}

public class Main {
    public static void main(String[] args) {
        java.util.List<Product> products = new java.util.ArrayList<>();
        products.add(new Product("Laptop", true, 800));
        products.add(new Product("Phone", false, 500));
        products.add(new Product("Tablet", true, 1200));
        products.add(new Product("Headphones", true, 150));

        Specification<Product> inStock = new InStockSpecification();
        Specification<Product> under1000 = new PriceBelowSpecification(1000);
        Specification<Product> affordableAndAvailable = new AndSpecification(inStock, under1000);

        // controlled entry point: run every product through the combined rule
        for (Product product : products) {
            if (affordableAndAvailable.isSatisfiedBy(product)) {
                System.out.println(product.getName() + " matches the combined specification");
            }
        }
    }
}

