#include <iostream>
#include <vector>
#include <string>

class Product {
public:
    std::string name;
    bool inStock;
    double price;

    Product(std::string name, bool inStock, double price)
        : name(name), inStock(inStock), price(price) {}
};

class Specification {
public:
    virtual bool isSatisfiedBy(const Product& candidate) const = 0;
    virtual ~Specification() = default;
};

class InStockSpecification : public Specification {
public:
    bool isSatisfiedBy(const Product& candidate) const override {
        // independent rule: only looks at stock, knows nothing about price
        return candidate.inStock;
    }
};

class PriceBelowSpecification : public Specification {
private:
    double limit; // each instance owns its own threshold

public:
    PriceBelowSpecification(double limit) : limit(limit) {}

    bool isSatisfiedBy(const Product& candidate) const override {
        // independent rule: only looks at price, knows nothing about stock
        return candidate.price < limit;
    }
};

class AndSpecification : public Specification {
private:
    const Specification& first;
    const Specification& second;

public:
    AndSpecification(const Specification& first, const Specification& second)
        : first(first), second(second) {}

    bool isSatisfiedBy(const Product& candidate) const override {
        // combinator: delegates to both wrapped specifications, combines with AND
        return first.isSatisfiedBy(candidate) && second.isSatisfiedBy(candidate);
    }
};

int main() {
    std::vector<Product> products;
    products.push_back(Product("Laptop", true, 800));
    products.push_back(Product("Phone", false, 500));
    products.push_back(Product("Tablet", true, 1200));
    products.push_back(Product("Headphones", true, 150));

    InStockSpecification inStock;
    PriceBelowSpecification under1000(1000);
    AndSpecification affordableAndAvailable(inStock, under1000);

    // controlled entry point: run every product through the combined rule
    for (const Product& product : products) {
        if (affordableAndAvailable.isSatisfiedBy(product)) {
            std::cout << product.name << " matches the combined specification" << std::endl;
        }
    }

    return 0;
}
